// Compares the C# QR port against the qrcodejs reference generated by qr_oracle.js.
// Usage: QrTest <reference.txt> <cases.tsv>
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace BiliGetter
{
    internal static class QrTest
    {
        private static int Main(string[] args)
        {
            string refPath = args.Length > 0 ? args[0] : "qr-reference.txt";
            string casesPath = args.Length > 1 ? args[1] : "qr-cases.tsv";

            // ---- parse reference ----
            var expected = new Dictionary<string, List<string>>();
            var errors = new Dictionary<string, string>();
            string curKey = null;
            List<string> curRows = null;
            foreach (string raw in File.ReadAllLines(refPath))
            {
                string line = raw.TrimEnd('\r');
                if (line.StartsWith("#")) continue;
                if (line.StartsWith("CASE "))
                {
                    string[] parts = line.Split(' ');
                    string name = parts[1];
                    string level = parts[2].Substring("level=".Length);
                    curKey = name + "|" + level;
                    if (line.Contains(" ERROR "))
                    {
                        errors[curKey] = line.Substring(line.IndexOf(" ERROR ") + 7);
                        curKey = null;
                        continue;
                    }
                    curRows = new List<string>();
                    expected[curKey] = curRows;
                }
                else if (line == "ENDCASE") { curKey = null; curRows = null; }
                else if (curRows != null && line.Length > 0) curRows.Add(line);
            }

            var levels = new Dictionary<string, int> {
                { "L", QrTables.LevelL }, { "M", QrTables.LevelM },
                { "Q", QrTables.LevelQ }, { "H", QrTables.LevelH }
            };

            int pass = 0, fail = 0, skipped = 0;
            foreach (string raw in File.ReadAllLines(casesPath))
            {
                string line = raw.TrimEnd('\r');
                if (line.Length == 0) continue;
                string[] f = line.Split('\t');
                string name = f[0], lvlName = f[1];
                string text = Encoding.UTF8.GetString(HexToBytes(f[2]));
                string key = name + "|" + lvlName;

                if (errors.ContainsKey(key))
                {
                    // qrcodejs itself cannot encode this; verify we do not crash.
                    try { QrCode.Encode(text, levels[lvlName]); Console.WriteLine("NOTE  " + key + "  (qrcodejs errored; our port encodes it)"); }
                    catch (Exception ex) { Console.WriteLine("FAIL  " + key + "  ours threw: " + ex.Message); fail++; }
                    skipped++;
                    continue;
                }
                if (!expected.ContainsKey(key)) { Console.WriteLine("SKIP  " + key + "  no reference"); skipped++; continue; }

                List<string> want = expected[key];
                try
                {
                    QrCode qr = QrCode.Encode(text, levels[lvlName]);
                    int n = qr.ModuleCount;
                    int wantN = want[0].Length;
                    if (n != wantN)
                    {
                        Console.WriteLine("FAIL  " + key + "  module count ours=" + n + " ref=" + wantN);
                        fail++; continue;
                    }
                    string mismatch = null;
                    for (int r = 0; r < n && mismatch == null; r++)
                        for (int c = 0; c < n; c++)
                        {
                            char w = want[r][c];
                            bool got = qr.IsDark(r, c);
                            if ((w == '1') != got) { mismatch = "first diff at row=" + r + " col=" + c + " ours=" + (got ? 1 : 0) + " ref=" + w; break; }
                        }
                    if (mismatch == null) { Console.WriteLine("PASS  " + key + "  v" + qr.TypeNumber + " " + n + "x" + n); pass++; }
                    else { Console.WriteLine("FAIL  " + key + "  " + mismatch); fail++; }
                }
                catch (Exception ex) { Console.WriteLine("FAIL  " + key + "  threw: " + ex.Message); fail++; }
            }
            Console.WriteLine();
            Console.WriteLine("RESULT pass=" + pass + " fail=" + fail + " skipped/no-reference=" + skipped);
            return fail == 0 ? 0 : 1;
        }

        private static byte[] HexToBytes(string hex)
        {
            var b = new byte[hex.Length / 2];
            for (int i = 0; i < b.Length; i++) b[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
            return b;
        }
    }
}
